497	interface GlobalArgs {
498	  dataFile: string;
499	  help: boolean;
500	  rest: string[];
501	}
502	
503	function splitGlobalArgs(argv: string[]): GlobalArgs {
504	  const result: GlobalArgs = {dataFile: DEFAULT_DATA_FILE, help: false, rest: []};
505	  for (let i = 0; i < argv.length; i++) {
506	    const a = argv[i];
507	    if (a === '-h' || a === '--help') {
508	      result.help = true;
509	    } else if (a === '--data') {
510	      const v = argv[++i];
511	      if (v === undefined) throw new UsageError('选项 --data 缺少数据文件路径');
512	      result.dataFile = v;
513	    } else if (a.startsWith('--data=')) {
514	      result.dataFile = a.slice('--data='.length);
515	      if (result.dataFile === '') throw new UsageError('选项 --data 缺少数据文件路径');
516	    } else {
517	      result.rest.push(a);
518	    }
519	  }
520	  return result;
521	}
522	
523	interface ParsedFlags {
524	  values: Map<string, string[]>;
525	  positionals: string[];
526	}
527	
528	// 子命令选项解析：allowed 中列出的选项均需带值；multi 中的选项可重复
529	function parseFlags(args: string[], allowed: string[], multi: string[] = []): ParsedFlags {
530	  const allowedSet = new Set(allowed);
531	  const multiSet = new Set(multi);
532	  const values = new Map<string, string[]>();
533	  const positionals: string[] = [];
534	
535	  const takeValue = (key: string, inline: string | undefined, index: number): [string, number] => {
536	    if (inline !== undefined) return [inline, index];
537	    const v = args[index + 1];
538	    if (v === undefined || v.startsWith('-')) {
539	      throw new UsageError(`选项 --${key} 缺少值`);
540	    }
541	    return [v, index + 1];
542	  };
543	
544	  for (let i = 0; i < args.length; i++) {
545	    const a = args[i];
546	    if (a.startsWith('--')) {
547	      let key: string;
548	      let inline: string | undefined;
549	      const eq = a.indexOf('=');
550	      if (eq >= 0) {
551	        key = a.slice(2, eq);
552	        inline = a.slice(eq + 1);
553	      } else {
554	        key = a.slice(2);
555	      }
556	      if (!allowedSet.has(key)) throw new UsageError(`未知选项: --${key}`);
557	      let v: string;
558	      [v, i] = takeValue(key, inline, i);
559	      if (v === '') throw new UsageError(`选项 --${key} 的值不能为空`);
560	      if (!multiSet.has(key) && values.has(key)) {
561	        throw new UsageError(`选项 --${key} 只能指定一次`);
562	      }
563	      const list = values.get(key) ?? [];
564	      list.push(v);
565	      values.set(key, list);
566	    } else if (a.startsWith('-') && a !== '-') {
567	      throw new UsageError(`未知参数: ${a}`);
568	    } else {
569	      positionals.push(a);
570	    }
571	  }
572	  return {values, positionals};
573	}
574	
575	function requireFlag(values: Map<string, string[]>, key: string): string {
576	  const v = values.get(key)?.[0];
577	  if (v === undefined) throw new UsageError(`缺少必需选项 --${key}`);
578	  return v;
579	}
