669	async function cmdRescheduleBooking(args: string[]): Promise<void> {
670	  const {values, positionals} = parseFlags(args, ['start', 'end', 'resource'], ['resource']);
671	  if (positionals.length !== 1) {
672	    throw new UsageError('用法: reschedule-booking <预约标识> [--start ...] [--end ...] [--resource ...]');
673	  }
674	  const id = positionals[0];
675	
676	  const file = activeDataFile;
677	  const store = await loadStore(file);
678	  const booking = store.bookings.find((b) => b.id === id);
679	  if (!booking) throw new BizError(`未知预约标识: ${id}`);
680	  if (booking.status === 'cancelled') {
681	    throw new BizError(`预约 ${id} 已取消，不能改期`);
682	  }
683	
684	  const hasTime = values.has('start') || values.has('end');
685	  const hasResource = values.has('resource');
686	  if (!hasTime && !hasResource) {
687	    throw new BizError('未指定任何改动：请提供 --start/--end 修改时间，或 --resource 替换资源（可同时提供）');
688	  }
689	
690	  const startRaw = values.get('start')?.[0] ?? booking.start;
691	  const endRaw = values.get('end')?.[0] ?? booking.end;
692	  const startMin = parseDateTime(startRaw, '预约开始时间');
693	  const endMin = parseDateTime(endRaw, '预约结束时间');
694	  if (endMin <= startMin) {
695	    throw new BizError(`预约结束时间必须晚于开始时间（开始: ${startRaw}，结束: ${endRaw}），允许跨日`);
696	  }
697	
698	  let ids: string[] = booking.resourceIds;
699	  if (hasResource) {
700	    const resourceArgs = values.get('resource')!;
701	    ids = resolveResourceIds(store, resourceArgs);
702	  }
703	
704	  assertOpenCoverage(store, ids, startMin, endMin);
705	  // 改期检查排除自身
706	  assertNoConflicts(findConflicts(store, ids, startMin, endMin, id), store);
707	
708	  // 全部可用后整体替换旧安排并落盘；失败则本进程内存与磁盘上的原安排都不变。
709	  // seriesId 不随改期变化：改期后仍属原系列。
710	  booking.start = startRaw;
711	  booking.end = endRaw;
712	  booking.resourceIds = ids;
713	  await saveStore(file, store);
714	  console.log(`已改期预约 ${id}（标识保持不变）`);
715	  if (booking.seriesId) console.log(`  所属系列: ${booking.seriesId}（改期后仍属该系列）`);
716	  console.log(`  时间: ${startRaw} → ${endRaw}`);
717	  console.log(`  资源: ${formatResourceIds(store, ids)}`);
718	}
