741	// 读取清单文件：不可读、不是合法 JSON 均明确失败（绝不按空清单处理）
742	async function loadManifest(file: string): Promise<unknown> {
743	  let text: string;
744	  try {
745	    text = await readFile(file, 'utf8');
746	  } catch (err) {
747	    throw new BizError(`无法读取改期清单 ${file}: ${(err as Error).message}`);
748	  }
749	  try {
750	    return JSON.parse(text);
751	  } catch (err) {
752	    throw new BizError(`改期清单 ${file} 已损坏，不是合法 JSON：${(err as Error).message}`);
753	  }
754	}
