1068	// 按周展开系列：每项相对前一项将起止时间同时后移 7 个营业地日历日，
1069	// 时刻与跨日长度保持不变。任何一项超出四位年份范围即整体拒绝。
1070	function planWeeklyMembers(startMin: number, endMin: number, count: number): PlannedMember[] {
1071	  const members: PlannedMember[] = [];
1072	  for (let i = 0; i < count; i++) {
1073	    const s = startMin + i * 7 * 1440;
1074	    const e = endMin + i * 7 * 1440;
1075	    const startRaw = formatDateTime(s);
1076	    const endRaw = formatDateTime(e);
1077	    if (startRaw === null || endRaw === null) {
1078	      const nth = i + 1;
1079	      throw new BizError(
1080	        `系列第 ${nth} 项（约第 ${nth} 周）的时间超出四位年份范围（${MIN_YEAR}-${MAX_YEAR}），无法创建：` +
1081	          '请缩短次数或改选更早的首项时间',
1082	      );
1083	    }
1084	    members.push({startRaw, endRaw, startMin: s, endMin: e});
1085	  }
1086	  return members;
1087	}
